class Solution:
    def dailyTemperatures(self, T: List[int]) -> List[int]:
        lens = len(T)
        output = [0]*lens
        stack = []

        for i in range(lens):
            count = 1
            while stack and T[i]>T[stack[-1]]:
                output[stack[-1]] = i-stack[-1]
                stack.pop()
            stack.append(i)
        return output

class Solution:
    def dailyTemperatures(self, T):
        ans = [0] * len(T)
        stack = []
        for i, t in enumerate(T):
            while stack and T[stack[-1]] < t:
                cur = stack.pop()
                ans[cur] = i - cur
            stack.append(i)

        return ans

