            results.append(s[i-j:i+j+1])
            j+=1
        j = 0
        while i+j+1<len(s) and i-j>=0 and s[i+j+1] == s[i-j] :
            results.append(s[i:i+j+2])
            j+=1
        return results
    def countSubstrings(self, s: str) -> int:
