class Solution:
    def removeElements(self, head: ListNode, val: int) -> ListNode:
        headnode = head
        prev = None
        while head:
            head_next = head.next
            if head.val == val:
                if prev:
                    prev.next = head_next
                else:
                    headnode = head.next
                head = head_next
            else:
                prev = head
                head = head.next
        return headnode

