class Solution:
    def canFinish(self, numCourses,prerequisites):
        edge = [[] for _ in range(numCourses)]
        visited = [0 for _  in range(numCourses)]
        for x,y in prerequisites:
            edge[x].append(y)
        def dfs(i):
            if visited[i] == -1:
                return False
            if visited[i] == 1:
                return True
            visited[i] = -1
            for j in edge[i]:
                if not dfs(j):
                    return False
            visited[i] = 1
            return True
        for i in range(numCourses):
            if not dfs(i):
                return False
        return True

class Solution:
    def canFinish(self, n, pres):
        from collections import deque
        ind = [[] for _ in xrange(n)]  # indegree
        oud = [0] * n  # outdegree
        for p in pres:
            oud[p[0]] += 1
            ind[p[1]].append(p[0])
        dq = deque()
        for i in xrange(n):
            if oud[i] == 0:
                dq.append(i)
        k = 0
        while dq:
            x = dq.popleft()
            k += 1
            for i in ind[x]:
                oud[i] -= 1
                if oud[i] == 0:
                    dq.append(i)
        return k == n

