class Solution:
    def minSubArrayLen(self, s: int, nums: List[int]) -> int:
        low,high = 0,0
        results = []
        while low<len(nums) and high<len(nums):
            if sum(nums[low:high+1]) <s:
                high+=1
            elif sum(nums[low:high+1])  ==s:
                results.append(high+1-low)
                low+=1
            elif sum(nums[low:high+1]) > s:
                low+=1
        return min(results)

