class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        childs = [[] for _ in range(numCourses)]
        parent = [0 for _ in range(numCourses)]
        for x in prerequisites:
            childs[x[1]].append(x[0])
            parent[x[0]] +=1
        dq = deque()
        for i in range(len(parent)):
            if parent[i]==0:
                dq.append(i)
        order = []
        while dq:
            node = dq.popleft()
            order.append(node)
            for leaf in childs[node]:
                parent[leaf]-=1
                if parent[leaf] == 0:
                    dq.append(leaf)
        return order if len(order) == numCourses else []

