    def rob(self, nums: List[int]) -> int:
        nums1 = nums[:-1]
        nums2 = nums[1:]
        nums1[1] = max(nums1[0],nums1[1])
        nums2[1] = max(nums2[0],nums2[1])
        for i in range(2,len(nums1)):
