class Solution:
    def asteroidCollision(self, asteroids: List[int]) -> List[int]:
        left = []
        pos = []
        while asteroids:
            star = asteroids.pop()
            if star>0:
                popp = 0
                while len(left)>0 and star >= abs(left[-1]):
                    popp = left.pop()  
                if len(left) <= 0 and star>abs(popp):
                    pos.append(star)

