        right_most = len(matrix[0])-1
        for i in range(len(matrix)):
            if right_most<0:
                break
            else:
                #perform binary search
                left,right = 0,right_most
                while left<=right:
                    mid = (left+right)//2
                    if matrix[i][mid]==target:
                        return True
                    elif matrix[i][mid]>target:
                        right = mid-1
                        right_most = right
                    else:
                        left = mid+1
        return False

