class Solution:
    def minWindow(self, s: str, t: str) -> str:
        minWindow = s
        target = set()
        sett = set(list(t))
        interm = []
        res = []
        for i in range(len(minWindow)):
            if minWindow[i] in target and minWindow[i] == minWindow[interm[0]]:
                interm.pop(0)
            if minWindow[i] in sett :
                interm.append(i)
                target.add(minWindow[i])

            if target==sett:
                res.append(minWindow[interm[0]:interm[-1]+1])
                target.remove(minWindow[interm[0]])
                interm.pop(0)


        return min(res,key = lambda x : len(x)) if len(res)>0 else ""

