    def palindromePairs(self, words: List[str]) -> List[List[int]]:
        rev = {word[::-1]: i for i, word in enumerate(words)}
        res = []

        for i, word in enumerate(words):
            if word:
                for j in range(len(word)):
                    l, r = word[:j], word[j:]

                    if l in rev and i != rev[l] and r == r[::-1]:
                        res.append([i,rev[l]])

