        kmost = []
        mins = 0
        minw = ""
        for i in words:
            freq.setdefault(i,1)
            freq[i] +=1
        for word in freq:
            if len(kmost)<k:
                heapq.heappush(kmost,(freq[word],word))
                mins = kmost[0]
            elif len(kmost)==k and freq[word]>mins[0]:
                heapq.heappushpop(kmost,(freq[word],word))
            elif len(kmost)==k and freq[word]==mins[0]:
                if word<mins[1]:
                    heapq.heappop(kmost)
                    heapq.heappush(kmost,(freq[word],word))
        kmost.sort(key = lambda x: x[1])
        kmost.sort(key = lambda x: x[0],reverse = True)

        return [x[1] for x in kmost]

class Solution:
