class Solution:
    def findDiagonalOrder(self, matrix: List[List[int]]) -> List[int]:
        if not matrix or not matrix[0]:
            return []
        col = len(matrix[0])#3
        row = len(matrix)#3
        ress = []
        for i in range(row+col-1):
            res = []
            start = max(i-col+1,0)
            end = min(i+1,row)
            for c in range(start,end):
                x = c
                y = i-c
                res.append(matrix[x][y])
            if i%2==0:
                res = res[::-1]
            ress +=res
        return ress

class Solution:
    def findDiagonalOrder(self, matrix: List[List[int]]) -> List[int]:
        if not matrix or not matrix[0]:
