class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        stack = ["0"]
        num = list(num)
        for i in num:
            while int(i)<int(stack[-1]) and k>0:
                stack.pop()
                k-=1
            stack.append(i)
            # if k==0:
            #     break
        while k>0:
            stack.pop()
            k-=1

