class Solution:
    def dailyTemperatures(self, T: List[int]) -> List[int]:
        stack = [(float("inf"),0)]
        position = [0]*len(T)
        for i in range(len(T)):
            while T[i] >stack[-1][0]:
                temp = stack.pop()
                position[temp[1]] = i-temp[1]
            stack.append((T[i],i))
        return position

class Solution:
    def dailyTemperatures(self, T: List[int]) -> List[int]:
        n, right_max = len(T), float('-inf')
        res = [0] * n
        for i in range(n-1, -1, -1):
            t = T[i]
            if right_max <= t:
                right_max = t
            else:
                temp = 1
                while T[i+temp] <= t:
                    temp += res[i+temp]
                res[i] = temp
        return res

class Solution:
    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        dfn = [0] *(n+1)
        low = [float("inf")]*(n+1)
        g = collections.defaultdict(list)
        self.time = 1
        res = []
        parent = [-1]*(n+1)
        def tarjan(u):
            low[u] = self.time
            dfn[u] = self.time
            self.time+=1
            for v in g[u]:
                if not dfn[v]:
                    parent[v] = u
                    tarjan(v)
                    low[u] = min(low[u], low[v])
                    if low[v] >dfn[u]:
                        res.append([v,u])
                elif v != parent[u]:
                    low[u] = min(low[u],dfn[v])
        for x,y in connections:
            g[x].append(y)
            g[y].append(x)

        for i in range(1,1+n):
            if not dfn[i]:
                tarjan(i)
        return res

