        hashmap = {}
        sums =0
        res = 0
        for i in A:
            sums += i
            left = sums%K
            if sums%K not in hashmap:
                hashmap[sums%K] = 1
            else:
                hashmap[sums%K] +=1
            if left!=0:
                if hashmap[left]>=2:
                    res+=hashmap[left]-1
            else:
