        for i,account  in enumerate(accounts):
            for j in account[1:]:
                if j not in account_map:
                    account_map[j] = [i]
                else:
                    account_map[j].append(i)
        def dfs(account,emails):
            if account in visited:
                return 
            visited.add(account)
            for j in accounts[account][1:]:
                emails.add(j)
                for i in account_map[j]:
                    dfs(i,emails)
            return 

        visited = set()
        res = []
        for i,j in enumerate(accounts):
            name = j[0]
            emails = set()
            if i in visited:
                continue
            dfs(i,emails)
            res.append([name]+sorted(list(emails)))
        return res

