class Solution:
    def connect(self, root: 'Node') -> 'Node':
        if root is None:
            return root
        level = [root]
        while level:
            for i in range(len(level)-1):
                level[i].next = level[i+1]
            level[-1].next =  None
            next_level = []
            for node in level:
                if node.left:
                    next_level.append(node.left)
                if node.right:
                    next_level.append(node.right)
            level = next_level
        return root
    def connect(self, root):
        """
        :type root: TreeLinkNode
        :rtype: nothing
        """

        if not root:
            return None
        cur  = root
        next = root.left

        while cur.left :
            cur.left.next = cur.right
            if cur.next:
                cur.right.next = cur.next.left
                cur = cur.next
            else:
                cur = next
                next = cur.left
        return root

