class Solution:
    def minimumTotal(self, triangle: List[List[int]]) -> int:
        rows = len(triangle)
        table = [[0 for col in range(len(triangle[row]))] for row in range(rows)]

        #base case
        table[0][0] = triangle[0][0]
        #base case for last column
        for r in range(1, rows):
            col = len(triangle[r]) - 1
            col_prv = len(triangle[r - 1]) - 1
            table[r][col] = table[r - 1][col_prv] + triangle[r][col]
        #base case for first row
        for r in range(1,rows):
            table[r][0] = triangle[r][0] + table[r - 1][0]

        # fill up the rest
        for r in range(2,rows):
            for c in range(1, len(triangle[r]) - 1):
                table[r][c] = triangle[r][c] + min(table[r - 1][c -1], table[r - 1][c])

        return min(table[rows - 1])  # min from last row
    def minimumTotal(self, triangle: List[List[int]]) -> int:
        n = len(triangle)
        minlen = triangle[-1]
        for i in reversed(range(n-1)):
            for j in range(i+1):
                minlen[j] = min(minlen[j],minlen[j+1])+triangle[i][j]
        return minlen[0]

