class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums)<=0:
            return 0
        if len(nums) <=2:
            return max(nums)
        nums1 = nums[:-1]
        nums2 = nums[1:]
        nums1[1] = max(nums1[0],nums1[1])
        nums2[1] = max(nums2[0],nums2[1])
        for i in range(2,len(nums1)):
            nums1[i] = max(nums1[i-1],nums1[i]+nums1[i-2])

        for i in range(2,len(nums2)):
            nums2[i] = max(nums2[i-1],nums2[i]+nums2[i-2])

        return max(nums2[-1],nums1[-1])

