class Solution:
    def dfs(self,matrix,i,j,val):
        cur = matrix[i][j]
        pa,atl = False,False
        if cur<0:
            return pa,atl
        if cur>val:
            return pa,atl
        matrix[i][j] = -1
        dire = [-1,0,1]
        for ii in dire:
            for jj in dire:
                if abs(ii)==abs(jj):
                    continue
                if i+ii<0 or j+jj<0:
                    pa = True
                elif i+ii ==len(matrix) or j+jj == len(matrix[0]):
                    atl = True
                elif 0<=i+ii<len(matrix) and 0<=j+jj<len(matrix[0]):

                    p,a = self.dfs(matrix,i+ii,j+jj,cur)
                    pa = p or pa
                    atl = a or atl
                    if pa and atl:
                        break
        matrix[i][j] = cur
        return pa,atl

