class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        S = set(words)
        ans = []
        # check each word
        for word in words:
            if not word: continue
            stack = [0]
            seen = {0}
            M = len(word)
            while stack:
                node = stack.pop()
                # find all possible comb
                if node == M:
                    ans.append(word)
                    break
                    #check all possible length
                for j in range(M-node+1):
                    if (word[node:node+j] in S and 
                    node+j not in seen and (node>0 or node+j!=M)):
                        stack.append(node+j)
                        seen.add(node+j)
        return ans

