from collections import deque
class Solution:
    def canFinish(self, n, pres):

        ind = [[] for _ in range(n)]  # indegree
        oud = [0] * n  # outdegree
        for p in pres:
            oud[p[0]] += 1
            ind[p[1]].append(p[0])
        dq = deque()
        #加入级别最高的点
        for i in range(n):
            if oud[i] == 0:
                dq.append(i)
        k = 0
        #从级别最高的点遍历他的子课，当子课没有父课时加入dq

        while dq:
            x = dq.popleft()
            k += 1
            for i in ind[x]:
                oud[i] -= 1
                if oud[i] == 0:
                    dq.append(i)
        return k == n

    def canFinsih(self,n,pres):
        graph = [[] for _ in range(n)]
        visit = [0  for _ in range(n)]
        for x,y in pres:
            graph[x].append(y) 
        def dfs(i):
            if visit[i] == -1:
                return False
            if visit[i] == 1:
                return True
            visit[i] ==-1
            for j in graph[i]:
                if not dfs(i):
                    return False
            visit[i] = 1
            return True
        for i in range(n):
            if not dfs(i):
                return False
        return True

