            for j in range(i, n):
                if i != j and M[i][j] == 1 and find(i) != find(j):
                    circles[find(i)] = find(j)   

        return sum([1 for k, v in circles.items() if k == v])
    def findCircleNum(self,M):
        N = len(M)
        seen = set()
        def dfs(node):
            for nei,adj in enumerate(M[node]):
                if adj and nei not in seen:
                    seen.add(nei)
                    dfs(nei)
        ans = 0
        for i in range(N):
            if i not in seen:
                dfs(i)
                ans+=1
