class Solution:
    def cloneGraph(self, node: 'Node') -> 'Node':
        newnode = Node(node.val,[])
        visited = {node:newnode}
        visited = self.recu(node,visited)
        return visited[node]
    def recu(self,node,visited):
        i = 0
        newnode = visited[node]
        nums = len(node.neighbors)
        while i<nums:
            fri = node.neighbors[i]
            #create cloned node
            if fri not in visited:
                newfri = Node(fri.val,[])
                visited[fri] = newfri
                visited = self.recu(fri,visited)
            else:
                newfri = visited[fri]
            # set neighbours after creation
            newnode.neighbors.append(newfri)

            i+=1
        return visited
    def cloneGraph(self,node):
        if not node:
            return 
        copy = Node(node.val,[])
        dic = {node:copy}
        stack = [node]
        while stack:
            node = stack.pop()
            for nei in node.neighbors:
                if nei not in dic:
                    neicopy = Node(nei.val,[])
                    dic[nei] = neicopy
                    dic[node].neighbors.append(neicopy)
                    stack.append(nei)
                else:
                    dic[node].neighbors.append(dic[nei])
        return copy

