class Solution {
    public String longestPalindrome(String s) {
        char[] list = s.toCharArray();
        int i =0;
        String max="";
        int length = s.length();
        while (i<length){
            String local = findMax(i,i+1,list);
            String local2 = findMax(i, i, list);
            i++;
            max = maxString(local, local2, max);
        }
        return max;
    }

    private String findMax(int i, int j, char[] list){
        int size = list.length;
        if(i < 0 || j >=size ){
            return "";
        }
        while(i>=0 && j< size && list[i]==list[j]){
            i= i-1;
            j=j+1;
        }
        return String.valueOf(list).substring(i+1, j);
    }

    private String maxString(String a, String b, String c){
    if (c.length() >= a.length() && c.length() >= b.length()) return c;
    if (a.length() >= b.length()) return a;
    return b;
}

}

class Solution {
    public String longestPalindrome(String s) {
        if (s == null || s.length() < 2) return s;

        // 预处理：把 "abba" 变成 "^#a#b#b#a#$"，统一奇偶回文
        StringBuilder sb = new StringBuilder();
        sb.append('^');
        for (int i = 0; i < s.length(); i++) {
            sb.append('#').append(s.charAt(i));
        }
        sb.append("#$");
        String t = sb.toString();

        int n = t.length();
        int[] p = new int[n]; // p[i] = 以 i 为中心的回文“半径”（在 t 中的字符数）
        int center = 0, right = 0;

        int bestCenter = 0, bestLen = 0;

        for (int i = 1; i < n - 1; i++) {
            int mirror = 2 * center - i;

            if (i < right) {
                p[i] = Math.min(right - i, p[mirror]);
            }

            // 尝试继续扩展
            while (t.charAt(i + p[i] + 1) == t.charAt(i - p[i] - 1)) {
                p[i]++;
            }

            // 更新当前最右回文边界
            if (i + p[i] > right) {
                center = i;
                right = i + p[i];
            }

            // 记录最优
            if (p[i] > bestLen) {
                bestLen = p[i];
                bestCenter = i;
            }
        }

        // 从 t 映射回 s 的起点：
        // t 中每个原字符之间插了 '#', 且开头有 '^#'
        int start = (bestCenter - bestLen) / 2;
        return s.substring(start, start + bestLen);
    }
}

class Solution {
    public int maxArea(int[] height) {
        int i = 0;
        int j = height.length-1;
        int max = 0;
        while(i!=j){
            int area = getArea(i, j, height);
            max = Math.max(max, area);
            if(height[i]<height[j]){
                i++;
            } else{
                j--;
            }
        }
        return max;
    }

    private int getArea(int i, int j, int[] height){
        int heighti = height[i];
        int heightj = height[j];
        int area = Math.min(heighti, heightj)*(j-i);
        return area;
    }
}

