class Solution {
    public int threeSumClosest(int[] nums, int target) {
        Arrays.sort(nums);
        int mindist = 99;
        int value = 0;
        for (int i =0; i < nums.length - 1; i++){
            int j = i+1;
            int k = nums.length -1;
            int sum = target - nums[i];
            while (j<k){
                int diff = Math.abs(sum - nums[j] - nums[k]);
                if (diff< mindist){
                    mindist = diff;
                    value = nums[i] + nums[j] + nums[k];
                } else{
                    if( sum > nums[j] + nums[k]){
                        j++;
                    } else{
                        k--;
                    }
                }

            }

        }
        return value;
    }
}

