class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        Set<List<Integer>> list = new HashSet<>();
        Arrays.sort(nums);
        for (int i=0; i<nums.length-1;i++){
            for (int j = i+1; j< nums.length-1; j++){
                int k = j+1;
                int l = nums.length -1;
                while( k< l){
                    int sum = nums[i]+nums[j]+nums[k]+nums[l];
                    if (sum == target){
