class Solution {
    public int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int i = 0;          // 窗口左边界
        int max = 0;

        for (int j = 0; j < s.length(); j++) {
            char c = s.charAt(j);

            if (last.containsKey(c) && last.get(c) >= i) {
                i = last.get(c) + 1;   // 左边界跳到重复字符上次位置+1
            }

            last.put(c, j);
            max = Math.max(max, j - i + 1);
        }
        return max;
    }
}

class Solution {
    public int firstUniqChar(String s) {
        HashMap<Character, Integer> m = new HashMap<>();
        int min = s.length()+1;
        for(int i=0; i< s.length();i++){
            if( m.containsKey(s.charAt(i))){
                m.put(s.charAt(i), -1);
            } else {
                m.put(s.charAt(i), i);
            }
        }

        for ( Character c : m.keySet()){
            if(0<=m.get(c)){
                min = Math.min(min, m.get(c));
            }
        }

        return min == s.length()+1? -1: min;

    }
}

class Solution {
    public int firstUniqChar(String s) {
        if (s == null || s.isEmpty()) return -1;

        int[] cnt = new int[26];
        for (int i = 0; i < s.length(); i++) {
            cnt[s.charAt(i) - 'a']++;
        }
        for (int i = 0; i < s.length(); i++) {
            if (cnt[s.charAt(i) - 'a'] == 1) return i;
        }
        return -1;
    }
}

class Solution {
    public List<List<String>> groupAnagrams(String[] strs) {
        HashMap<String, List<String>> m = new HashMap<>();
        List<List<String>> result = new ArrayList<>();
        for ( String s : strs){
            String sorted = sortString(s);
            m.computeIfAbsent(sorted, k->new ArrayList<>()).add(s);
        }
        for (List<String> list: m.values()){
result.add(list);
        }

        return result;
    }

    public static String sortString(String s) {
    char[] arr = s.toCharArray();
    Arrays.sort(arr);
    return new String(arr);
}
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public List<Integer> postorderTraversal(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        helper(result, root);

        return result;
    }

    private void helper(List<Integer> r, TreeNode node){
        if(node == null){
            return;
        }

        helper(r, node.left);
        helper(r, node.right);
        r.add(node.val);
    }
}

