 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public List<Integer> postorderTraversal(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        push(root, stack);
        while(stack.size()!=0){
            TreeNode node = stack.pop();
            if(node != null){
                           result.add(node.val);
                                       push(node.left, stack);

            push(node.right, stack);
            }

        }
        Collections.reverse(result);
        return result;
    }

    private void push(TreeNode node, Deque<TreeNode> stack){
        if(node==null){
            return;
        }
        stack.push(node);
    }

    private void helper(List<Integer> r, TreeNode node){
        if(node == null){
            return;
        }

        helper(r, node.left);
        helper(r, node.right);
        r.add(node.val);
    }
}

