class Solution {
    public String removeDuplicates(String s) {
        ArrayDeque<Character> r = new ArrayDeque<>();

        for (char ch : s.toCharArray()) {
            if (!r.isEmpty() && r.peek() == ch) {
                r.pop();
            } else {
                r.push(ch);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (char c : r) sb.append(c);

        return sb.reverse().toString();
    }
}

class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        ArrayDeque<Integer> l = new ArrayDeque<>();
        int[] r = new int[temperatures.length];
        for (int i=0; i< temperatures.length; i++){
            while(!l.isEmpty() && temperatures[i]>temperatures[l.peek()] ){
                int newi = l.pop();
                r[newi] = i-newi;
            }
            l.push(i);
        }

        while(!l.isEmpty()){
                    int newi = l.pop();
                    r[newi]=0;
                    }
        return r;
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode reverseList(ListNode head) {
        if(head == null){
            return head;
        }
        ListNode h = head;
        while(h.next!=null){
            h = h.next;
        }
        helper(head);
        head.next = null;
        return h;
    }

    private ListNode helper(ListNode node){
        if(node.next == null){
            return node;
        }
        ListNode newNode = helper(node.next);
        newNode.next = node;
        return node;
    }
}

