 * Your Twitter object will be instantiated and called as such:
 * Twitter obj = new Twitter();
 * obj.postTweet(userId,tweetId);
 * List<Integer> param_2 = obj.getNewsFeed(userId);
 * obj.follow(followerId,followeeId);
 * obj.unfollow(followerId,followeeId);
 */

class Twitter {
    private static class Tweet {
        int id;
        int time;
        Tweet next;
        Tweet(int id, int time, Tweet next) { this.id = id; this.time = time; this.next = next; }
    }

    private int time = 0;
    private final Map<Integer, Tweet> head = new HashMap<>();           // user -> latest tweet (linked list)
    private final Map<Integer, Set<Integer>> followees = new HashMap<>(); // follower -> followee set

    public Twitter() {}

    public void postTweet(int userId, int tweetId) {
        Tweet curHead = head.get(userId);
        head.put(userId, new Tweet(tweetId, time++, curHead)); // 头插，最新在前
    }

    public List<Integer> getNewsFeed(int userId) {
        // 堆里放每个用户当前指向的“最新tweet节点”，每次弹出最新的，再推进该用户链表的下一条
        PriorityQueue<Tweet> pq = new PriorityQueue<>((a, b) -> Integer.compare(b.time, a.time));

        Tweet self = head.get(userId);
        if (self != null) pq.offer(self);

        Set<Integer> fs = followees.get(userId);
        if (fs != null) {
            for (int f : fs) {
                Tweet t = head.get(f);
                if (t != null) pq.offer(t);
            }
        }

        List<Integer> res = new ArrayList<>(10);
        while (!pq.isEmpty() && res.size() < 10) {
            Tweet t = pq.poll();
            res.add(t.id);
            if (t.next != null) pq.offer(t.next);
        }
        return res;
    }

    public void follow(int followerId, int followeeId) {
        if (followerId == followeeId) return; // 避免自己关注自己
        followees.computeIfAbsent(followerId, k -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> s = followees.get(followerId);
        if (s != null) s.remove(followeeId);
    }
}

