 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    ListNode cache;

    public Solution(ListNode head) {
        cache = head;
    }

    public int getRandom() {
        ListNode start = cache;
        Random r = new Random();
        int x = r.nextInt(10^4);
        int i = 0;
        if(start == null){
            return 0;
        }
        while(i < x){
            if(start.next == null){
                start.next = cache;
            }
            i++;
            start = start.next;
        }
        return start.val;
    }
}

