    public int findDuplicate(int[] nums) {
        int i = 0;
        int length = nums.length-1;
        while(i<=length){
            int next = nums[i];
            if(next ==  i){
                return next;
            } 
            if(next == 0){
                return i;
            }
            nums[i] = 0;
            i = next;
        }
        return i;
    }
}

