import java.util.*;

class Solution {
    public List<Integer> findMinHeightTrees(int n, int[][] edges) {
        if (n <= 2) {
            List<Integer> ans = new ArrayList<>();
            for (int i = 0; i < n; i++) ans.add(i);
            return ans;
        }

        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        int[] deg = new int[n];

        for (int[] e : edges) {
            int a = e[0], b = e[1];
            g.get(a).add(b);
            g.get(b).add(a);
            deg[a]++; deg[b]++;
        }

        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (deg[i] == 1) q.add(i);
        }

        int remaining = n;
        while (remaining > 2) {
            int sz = q.size();
            remaining -= sz;
            for (int k = 0; k < sz; k++) {
                int leaf = q.poll();
                for (int nei : g.get(leaf)) {
                    if (--deg[nei] == 1) q.add(nei);
                }
            }
        }

        return new ArrayList<>(q);
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public int rob(TreeNode root) {
        int a = helper(root, true);
        int b = helper(root, false);
        return Math.max(a, b);
    }

    private int helper(TreeNode node, boolean stolen) {
        if (node == null) {
            return 0;
        }
        int right1 = helper(node.right, false);
        int left1 = helper(node.left, false);
        int total1 = right1 + left1;
        int right2 = helper(node.right, true);
        int left2 = helper(node.left, true);
        int total2 = left2 + right2 + node.val;
        if (stolen) {
            return total1;
        }
        return Math.max(total1, total2);
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    private Map<TreeNode, List<Integer>> m = new HashMap<>();
    public int rob(TreeNode root) {
        int a = helper(root, true);
        int b = helper(root, false);
        return Math.max(a, b);
    }

    private int helper(TreeNode node, boolean stolen) {
        if (node == null) {
            return 0;
        }
        if(m.containsKey(node)){
            int y = m.get(node).get(0);
            int n = m.get(node).get(1);
            if(stolen){
                return y;
            } else{
                return Math.max(y,n);
            }
        }
        int right1 = helper(node.right, false);
        int left1 = helper(node.left, false);
        int total1 = right1 + left1;
        int right2 = helper(node.right, true);
        int left2 = helper(node.left, true);
        int total2 = left2 + right2 + node.val;
        List<Integer> mm = List.of(total1, total2);
        m.put(node, mm);
        if (stolen) {
            return total1;
        }
        return Math.max(total1, total2);
    }
}

class Solution {
    private final Map<TreeNode, int[]> memo = new HashMap<>();
    // memo.get(node) = new int[]{skip, take}

    public int rob(TreeNode root) {
        int[] res = dfs(root);
        return Math.max(res[0], res[1]);
    }

    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        if (memo.containsKey(node)) return memo.get(node);

        int[] L = dfs(node.left);
        int[] R = dfs(node.right);

        int skip = Math.max(L[0], L[1]) + Math.max(R[0], R[1]);
        int take = node.val + L[0] + R[0];

        int[] ans = new int[]{skip, take};
        memo.put(node, ans);
        return ans;
    }
}

class Solution {
    public int rob(TreeNode root) {
        int[] res = dfs(root);
        return Math.max(res[0], res[1]);
    }

    // returns [skip, take]
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};

        int[] L = dfs(node.left);
        int[] R = dfs(node.right);

        int skip = Math.max(L[0], L[1]) + Math.max(R[0], R[1]);
        int take = node.val + L[0] + R[0];

        return new int[]{skip, take};
    }
}

class Solution {
    public boolean canMeasureWater(int x, int y, int target) {
        int gcd = gcd(x,y);
        int v = target%gcd;
        if(v!=0){
            return false;
        }
        return true;

    }

    private int gcd(int a, int b) {
        int t=0;
        while (b != 0) {
            t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

