            return false;
        }
        int gcd = gcd(x,y);
        int v = target%gcd;
        if(v!=0){
            return false;
        }
        return true;

    }

    private int gcd(int a, int b) {
        int t=0;
        while (b != 0) {
            t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

class Solution {

    private Map<Integer, Integer> memo = new HashMap<>();

    public int numSquares(int n) {
        int p = helper(n);
        return p;
    }

    private int least(int n) {
        int v = (int) Math.sqrt((double) n);
        return v;
    }

    private int helper(int n) {
        if (n == 0) {
            return 0;
        }
        if (n == 1) {
            return 1;
        }
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        int min = n;
        int i = least(n);
        while (i >= 1) {
            int result = helper(n - (int) Math.pow(i, 2));
            min = Math.min(result, min);
            i--;
        }
        memo.put(n, min + 1);
        return min + 1;
    }
}

class Solution {
    private final Map<Integer, Integer> memo = new HashMap<>();

    public int numSquares(int n) {
        return dfs(n);
    }

    private int dfs(int n) {
        if (n == 0) return 0;
        Integer cached = memo.get(n);
        if (cached != null) return cached;

        int best = Integer.MAX_VALUE;
        int r = (int) Math.sqrt(n);
        for (int i = r; i >= 1; --i) {
            int sq = i * i;
            best = Math.min(best, 1 + dfs(n - sq));
        }
        memo.put(n, best);
        return best;
    }
}

import java.util.*;

class Solution {
    public int numSquares(int n) {
        // 1) squares
        List<Integer> squares = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) squares.add(i * i);

        // 2) BFS
        ArrayDeque<Integer> q = new ArrayDeque<>();
        boolean[] visited = new boolean[n + 1];

        q.add(n);
        visited[n] = true;

        int steps = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            steps++; // this layer uses one more square
            for (int k = 0; k < size; k++) {
                int cur = q.poll();
                for (int sq : squares) {
                    int next = cur - sq;
                    if (next < 0) break;      // squares increasing, can stop
                    if (next == 0) return steps;
                    if (!visited[next]) {
                        visited[next] = true;
                        q.add(next);
                    }
                }
            }
        }
        return steps; // unreachable for n>=1
    }
}

