class Solution:
    def calcEquation(
        self, equations: List[List[str]], values: List[float], queries: List[List[str]]
    ) -> List[float]:
        graph: Dict[str, Dict[str, float]] = defaultdict(dict)

        for (a, b), v in zip(equations, values):
            graph[a][b] = v
            graph[b][a] = 1.0 / v

        ans = []
        for src, dst in queries:
            ans.append(self.bfs(src, dst, graph))
        return ans

    def bfs(self, src: str, dst: str, graph: Dict[str, Dict[str, float]]) -> float:
        if src not in graph or dst not in graph:
            return -1.0
        if src == dst:
            return 1.0

        q = deque([(src, 1.0)])
        visited = {src}

        while q:
            node, prod = q.popleft()
            if node == dst:
                return prod

            for nei, w in graph[node].items():
                if nei in visited:
                    continue
                visited.add(nei)
                q.append((nei, prod * w))

        return -1.0

class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        adj = defaultdict(list)

        for i, (u,v) in enumerate(equations):
            adj[u].append((v, values[i]))
            adj[v].append((u, 1/values[i]))
        def bfs(src, target):
            if src not in adj or target not in adj:
                return -1.

            queue, visited = deque(), set()
            queue.append((src, 1))
            visited.add(src)

            while len(queue) > 0:
                x, w = queue.popleft()
                if x == target:
                    return w
                for nei, rate in adj[x]:
                    if nei not in visited:
                        visited.add(nei)
                        queue.append((nei, w * rate))

            return -1.

        return [bfs(q[0], q[1]) for q in queries]

