class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        n = len(word1);
        m = len(word2);
        mat = [[0]*(n+1) for _ in range(m+1)];
        for i in range(n+1):
            mat[0][i] = i;
        for j in range(m+1):
            mat[j][0] = j;
        for i in range(1, n+1):
            for j in range(1, m+1):
                if word1[i-1] == word2[j-1]:
                    mat[j][i] = mat[j-1][i-1];
                else:
                    mat[j][i] = 1+min(mat[j-1][i], mat[j-1][i-1], mat[j][i-1]);
        return mat[m][n];

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        dp = list(range(n + 1))  # i=0 的那一行

        for i in range(1, m + 1):
            prev = dp[0]     # dp[i-1][0]
            dp[0] = i        # dp[i][0]
            for j in range(1, n + 1):
                tmp = dp[j]  # 还没更新前的 dp[i-1][j]
                if word1[i - 1] == word2[j - 1]:
                    dp[j] = prev
                else:
                    dp[j] = 1 + min(
                        dp[j],      # delete: dp[i-1][j]
                        dp[j - 1],  # insert: dp[i][j-1]
                        prev        # replace: dp[i-1][j-1]
                    )
                prev = tmp
        return dp[n]

