class Solution:
    def maximumGap(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 2:
            return 0
        mn, mx = min(nums), max(nums)
        if mn == mx:
            return 0

        w = max(1, (mx - mn) // (n - 1))
        cnt = (mx - mn) // w + 1

        bmin = [None] * cnt
        bmax = [None] * cnt

        for x in nums:
            i = (x - mn) // w
            if bmin[i] is None:
                bmin[i] = bmax[i] = x
            else:
                if x < bmin[i]: bmin[i] = x
                if x > bmax[i]: bmax[i] = x

        ans = 0
        prev = None
        for i in range(cnt):
            if bmin[i] is None:
                continue
            if prev is not None:
                ans = max(ans, bmin[i] - prev)
            prev = bmax[i]
        return ans

