class Solution:
    def checkSubarraySum(self, nums: List[int], k: int) -> bool:
        size = len(nums);
        i = 0;
        total = nums[i];
        memo = dict()
        while(i<size-1):
            j = i+1;
            while j < size:
                if (0, i-1) in memo and (0,j) in memo:
                    total = memo[(0,j)] - memo[(0,i-1)];
                else:
                    total += nums[j];
                    memo[(i,j)] = total;
                if(total % k == 0):
                    return True;
                j+=1;
            i+=1;
            total = nums[i];
        return False;

