class Solution:
    def checkSubarraySum(self, nums: List[int], k: int) -> bool:
        remainder_index = {0: -1}   # 前缀和余数 -> 最早出现的位置
        prefix = 0

        for i, num in enumerate(nums):
            prefix += num
            r = prefix % k

            if r in remainder_index:
                if i - remainder_index[r] >= 2:
                    return True
            else:
                remainder_index[r] = i

        return False

class Solution:
    def mostFrequentEven(self, nums: List[int]) -> int:
        r = dict();
        minx = -1;
        maxs = 0;
        for x in nums:
            if x in r:
                r[x] +=1;
            else:
                r[x] = 1;
            if r[x] > maxs and x %2 ==0:
                maxs = r[x];
                minx = x;
            if r[x] == maxs and x %2 ==0:
                minx = min(x, minx);
        return minx;

class Solution:
    def mostFrequentEven(self, nums: List[int]) -> int:
        cnt = {}
        ans = -1
        max_freq = 0

        for x in nums:
            if x % 2 != 0:
                continue

            cnt[x] = cnt.get(x, 0) + 1

            if cnt[x] > max_freq:
                max_freq = cnt[x]
                ans = x
            elif cnt[x] == max_freq:
                ans = min(ans, x)

        return ans

