class Solution:
    def numRescueBoats(self, people: List[int], limit: int) -> int:
        people.sort();
        i = 0;
        j = len(people)-1;
        boatcount = 0;
        while i< j:
            capa = people[j]+people[i];
            if capa > limit:
                boatcount +=1;
                j-=1;
            elif capa<=limit:
                i+=1;
                j-=1;
                boatcount +=1;
        if i==j:
            boatcount +=1;
        return boatcount;

