# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def swapNodes(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        dummy = ListNode(0, head);
        first = dummy;
        p = k-1;
        size = 0;
        while p > 0:
            first = first.next;
            p-=1;
            size +=1;
        end = first;
        while end.next:
            end = end.next;
            size+=1;

        second = dummy;
        p = size-k;
        while p>0:
            second = second.next;
            p-=1;

        if k > size - k:
            middle = second;
            second = first;
            first = middle;

        if first.next == second:
            middle = second.next;
            second.next = second.next.next;
            first.next = middle;
            first.next.next = second;
            return dummy.next;
        middle = first.next;
        middlenext = first.next.next
        first.next = second.next;
        middle.next = second.next.next;
        second.next = middle;
        first.next.next = middlenext;
        return dummy.next;

