class Solution:
    def swapNodes(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        first = head;
        for i in range(k-1):
            first = first.next;
        fast = first;
        second = head;
        while fast.next:
            fast = fast.next;
            second = second.next;
        second.val, first.val = first.val, second.val;
        return head;

