class Solution:
    def removeLeafNodes(self, root: Optional[TreeNode], target: int) -> Optional[TreeNode]:
        self.helper(root,target);
        return root;

    def helper(self, node: Optional[TreeNode], target: int)-> bool:
        if node is None:
            return True;
        if node.left:
            left = self.helper(node.left, target);
            if left:
                node.left = None;
        if node.right:
            right = self.helper(node.right, target);
            if right:
                node.right = None;

        if node.right is None and node.left is None and node.val == target:
            return True;

