class Solution:
    def removeLeafNodes(self, root: Optional[TreeNode], target: int) -> Optional[TreeNode]:
        return None if self.helper(root, target) else root

    def helper(self, node: Optional[TreeNode], target: int) -> bool:
        if node is None:
            return False

        if node.left and self.helper(node.left, target):
            node.left = None

        if node.right and self.helper(node.right, target):
            node.right = None

        return node.left is None and node.right is None and node.val == target

