class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        return self.build(grid, 0, 0, len(grid))

    def build(self, grid: List[List[int]], r: int, c: int, size: int) -> 'Node':
        if size == 1:
            return Node(grid[r][c] == 1, True, None, None, None, None)

        first = grid[r][c]
        same = True
        for i in range(r, r + size):
            for j in range(c, c + size):
                if grid[i][j] != first:
                    same = False
                    break
            if not same:
                break

        if same:
            return Node(first == 1, True, None, None, None, None)

        half = size // 2
        topLeft = self.build(grid, r, c, half)
        topRight = self.build(grid, r, c + half, half)
        bottomLeft = self.build(grid, r + half, c, half)
        bottomRight = self.build(grid, r + half, c + half, half)

        return Node(True, False, topLeft, topRight, bottomLeft, bottomRight)

def build_prefix(grid):
    n = len(grid)
    m = len(grid[0])
    pre = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            pre[i][j] = (
                pre[i - 1][j]
                + pre[i][j - 1]
                - pre[i - 1][j - 1]
                + grid[i - 1][j - 1]
            )
    return pre


def get_sum(pre, r1, c1, r2, c2):
    return (
        pre[r2 + 1][c2 + 1]
        - pre[r1][c2 + 1]
        - pre[r2 + 1][c1]
        + pre[r1][c1]
    )

class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        n = len(grid)
        pre = [[0] * (n + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for j in range(1, n + 1):
                pre[i][j] = (
                    pre[i - 1][j]
                    + pre[i][j - 1]
                    - pre[i - 1][j - 1]
                    + grid[i - 1][j - 1]
                )

        def get_sum(r: int, c: int, size: int) -> int:
            r2 = r + size - 1
            c2 = c + size - 1
            return (
                pre[r2 + 1][c2 + 1]
                - pre[r][c2 + 1]
                - pre[r2 + 1][c]
                + pre[r][c]
            )

        def build(r: int, c: int, size: int) -> 'Node':
            total = get_sum(r, c, size)

            if total == 0:
                return Node(False, True, None, None, None, None)

            if total == size * size:
                return Node(True, True, None, None, None, None)

            half = size // 2
            topLeft = build(r, c, half)
            topRight = build(r, c + half, half)
            bottomLeft = build(r + half, c, half)
            bottomRight = build(r + half, c + half, half)

            return Node(True, False, topLeft, topRight, bottomLeft, bottomRight)

        return build(0, 0, n)

