class Solution:
    def insertIntoBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        head = root;
        prev = head;
        while head:
            if head.val < val:
                prev = head;
                head = head.right
            else:
                prev = head;
                head = head.left
        node = TreeNode(val, None, None);
        if prev.val > val:
            prev.left = node;
        else:
            prev.right = node;
        return root;

