import heapq

class Solution:
    def longestDiverseString(self, a: int, b: int, c: int) -> str:
        pq = []
        if a > 0:
            heapq.heappush(pq, (-a, 'a'))
        if b > 0:
            heapq.heappush(pq, (-b, 'b'))
        if c > 0:
            heapq.heappush(pq, (-c, 'c'))

        res = []

        while pq:
            count1, ch1 = heapq.heappop(pq)

            # 如果再放 ch1，会出现三个连续相同字符
            if len(res) >= 2 and res[-1] == ch1 and res[-2] == ch1:
                if not pq:
                    break

                count2, ch2 = heapq.heappop(pq)
                res.append(ch2)
                count2 += 1   # 负数加1，表示用掉一个

                if count2 < 0:
                    heapq.heappush(pq, (count2, ch2))
                heapq.heappush(pq, (count1, ch1))
            else:
                res.append(ch1)
                count1 += 1

                if count1 < 0:
                    heapq.heappush(pq, (count1, ch1))

        return ''.join(res)

