class Solution:
    def makesquare(self, matchsticks: List[int]) -> bool:
        total = sum(matchsticks);
        if total%4 !=0:
            return False;
        side = total//4;
        buckets = [0]*4;
        matchsticks.sort(reverse = True);
        def dfs(index: int)->bool:
            if index == len(matchsticks):
                return True;
            for i in range(4):
                if buckets[i] + matchsticks[index]>side:
                    continue;
                buckets[i] += matchsticks[index];
                if dfs(index+1):
                    return True;
                buckets[i] -= matchsticks[index];
                if buckets[i] == 0:
                    return False;
            return False;
        return dfs(0);

class Solution:
    def combine(self, n: int, k: int) -> List[List[int]]:
        if k == 1:
            return [[i] for i in range(1,n+1)];
        if n < k:
            return [];
        result = self.combine(n-1, k-1);
        for j in result:
            j.append(n);
        return result + self.combine(n-1, k);

