class Solution:
    def findRedundantConnection(self, edges: List[List[int]]) -> List[int]:
        n = len(edges)
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])   # 路径压缩
            return parent[x]

        def union(x: int, y: int) -> bool:
            rx = find(x)
            ry = find(y)

            if rx == ry:
                return False

            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

            return True

        for u, v in edges:
            if not union(u, v):
                return [u, v]

        return []

