            dp = nxt

        return min(abs(s) for s in dp)

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        n = len(prices);
        hold = -prices[0];
        rest = 0;
        sell = 0;
        prev_hold = 0;
        prev_rest = 0;
        prev_sell = 0;
        for i in range(1,n):
            prev_hold = hold;
            prev_rest = rest;
            prev_sell = sell;
            hold = max(prev_hold, rest-prices[i]);
            sell = prev_hold + prices[i];
