class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:

        intervals.sort(key = lambda x: x[1]);
        prev = None;
        removal = 0;
        for ii in intervals:
            if prev is None:
                prev = ii;
                continue;
            if (prev[0]<=ii[0] and ii[0]<prev[1]) or (ii[0]<prev[1] and prev[1]<=ii[1]):
                removal +=1;
            else:
                prev = ii;
        return removal;

