class Solution:
    def insertGreatestCommonDivisors(self, head: Optional[ListNode]) -> Optional[ListNode]:
        def helper(a:int, b:int)->int:
            if a<b:
                a,b = b,a;
            while a%b!=0:
                a,b = b,a%b;
            return b;

        start = head;
        prev = None;
        while start.next:
            a = start.val;
            b = start.next.val;
            di = helper(a,b);
            newnode = ListNode(di,start.next);
            start.next = newnode;
            start = newnode.next;
        return head;

