class Solution:
    def minMutation(self, startGene: str, endGene: str, bank: List[str]) -> int:
        bank_set = set(bank)
        if endGene not in bank_set:
            return -1

        q = deque([startGene])
        choices = ["A", "C", "G", "T"]
        steps = 0

        while q:
            for _ in range(len(q)):
                gene = q.popleft()

                if gene == endGene:
                    return steps

                gene_list = list(gene)

                for i in range(len(gene_list)):
                    old = gene_list[i]

                    for c in choices:
                        if c == old:
                            continue

                        gene_list[i] = c
                        nxt = ''.join(gene_list)

                        if nxt in bank_set:
                            q.append(nxt)
                            bank_set.remove(nxt)  # mark visited

                    gene_list[i] = old  # restore

            steps += 1

        return -1

