class Trie:

    def __init__(self):
        self.map = defaultdict();

    def insert(self, word: str) -> None:

        def buildmap(word:str)->dict:
            if len(word) == 0:
                return {"":""};
            else:
                return {word[0]: buildmap(word[1:])};

        start = self.map;
        for i in range(len(word)):
            if word[i] not in start:
                start[word[i]] = buildmap(word[i+1:]);
                return;
            start = start[word[i]];
        start[""] = "";

    def search(self, word: str) -> bool:
        start = self.map;
        for i in range(len(word)):
            if word[i] not in start:
                return False;
            start = start[word[i]];
        print(start);
        return '' in start;
    def startsWith(self, prefix: str) -> bool:
        start = self.map;
        for i in range(len(prefix)):
            if prefix[i] not in start:
                return False;
            start = start[prefix[i]];
        return True;



