        node = self.map;
        for ch in word:
            if ch not in node:
                return False;
            node = node[ch];
        return '#' in node;
    def startsWith(self, prefix: str) -> bool:
        node = self.map;
        for ch in prefix:
            if ch not in node:
                return False;
            node = node[ch];
        return True;



