class Solution:
    def longestPalindrome(self, s: str) -> str:
        if not s:
            return ""

        t = "^#" + "#".join(s) + "#$"
        n = len(t)

        p = [0] * n
        center = 0
        right = 0

        max_len = 0
        max_center = 0

        for i in range(1, n - 1):
            mirror = 2 * center - i

            if i < right:
                p[i] = min(right - i, p[mirror])

            while t[i + p[i] + 1] == t[i - p[i] - 1]:
                p[i] += 1

            if i + p[i] > right:
                center = i
                right = i + p[i]

            if p[i] > max_len:
                max_len = p[i]
                max_center = i

        start = (max_center - max_len) // 2
        return s[start:start + max_len]

class Solution:
    def countSubstrings(self, s: str) -> int:
        # "abba" -> "^#a#b#b#a#$"
        t = "^#" + "#".join(s) + "#$"
        n = len(t)

        p = [0] * n
        center = 0
        right = 0

        for i in range(1, n - 1):
            mirror = 2 * center - i

            # 如果 i 在当前最右回文范围内，可以借用 mirror 的半径
            if i < right:
                p[i] = min(right - i, p[mirror])

            # 继续向外扩展
            while t[i + p[i] + 1] == t[i - p[i] - 1]:
                p[i] += 1

            # 更新当前最右回文
            if i + p[i] > right:
                center = i
                right = i + p[i]

        # p[i] 是改造后字符串里的半径
        # 每个中心贡献 (p[i] + 1) // 2 个原字符串回文子串
        return sum((x + 1) // 2 for x in p)

