class NumArray:

    def __init__(self, nums: List[int]):
        self.n = len(nums);
        self.tree = [0] * 4* self.n;
        self.nums = nums;
        if self.n>0:
            self.build(1, 0, self.n-1);

    def build(self, node:int, l:int, r:int)->None:
        if l==r:
            self.tree[node] = self.nums[l];
            return;
        mid = (l+r)//2;
        self.build(2*node, l, mid);
        self.build(2*node+1, mid+1, r);
        self.tree[node] = self.tree[2*node] + self.tree[2*node+1];


    def _update(self, node:int, l:int, r:int,index: int, val: int) -> None:
        if l == r:
            self.tree[node] = val;
            return;
        mid = (l+r)//2;
        if index<=mid:
            self._update(2*node, l, mid,index, val);
        else:
            self._update(2*node+1, mid+1, r, index, val);
        self.tree[node] = self.tree[2*node] + self.tree[2*node+1];
        return;

    def update(self, index: int, val: int) -> None:
        self._update(1, 0, self.n-1, index, val);


    def _query(self, node:int, l:int, r:int, ql:int, qr:int)->int:
        if r<ql or l>qr:
            return 0;
        if ql<=l and qr>=r:
            return self.tree[node];
        mid = (l+r)//2;
        left = self._query(2*node, l, mid, ql, qr);
        right = self._query(2*node+1, mid+1, r, ql, qr);
        total = left+right;
        return total; 
    def sumRange(self, left: int, right: int) -> int:
        return self._query(1, 0, self.n-1, left, right);






