class NumArray:

    def __init__(self, nums: List[int]):
        self.nums = nums[:]
        self.n = len(nums)
        self.size = int(self.n ** 0.5) + 1
        self.blocks = [0] * self.size

        for i, x in enumerate(nums):
            self.blocks[i // self.size] += x

    def update(self, index: int, val: int) -> None:
        block_id = index // self.size
        self.blocks[block_id] += val - self.nums[index]
        self.nums[index] = val

    def sumRange(self, left: int, right: int) -> int:
        total = 0

        while left <= right and left % self.size != 0:
            total += self.nums[left]
            left += 1

        while left + self.size - 1 <= right:
            total += self.blocks[left // self.size]
            left += self.size

        while left <= right:
            total += self.nums[left]
            left += 1

        return total

