class Fernwick:
    def __init__(self, n):
        self.tree = [0]*(n+1);
        self.n = n;
    def add(self, i, delta):
        i = i+1;
        while i<=self.n:
            self.tree[i] += delta;
            i += i & -i;
    def prefix_sum(self, i):
        i =i+1;
        result = 0;
        while i>0:
            result+=self.tree[i];
            i -= i&-i;
        return result;
    def range_sum(self, l, r):
        if l ==0:
            return self.prefix_sum(r);
        else:
            return self.prefix_sum(r)-self.prefix_sum(l-1);


class NumArray:

    def __init__(self, nums: List[int]):
        self.nums = nums[:]
        self.n = len(nums)
        self.bit = Fernwick(self.n);
        for i in range(self.n):
            self.bit.add(i,nums[i]);

    def update(self, index: int, val: int) -> None:
        ori = self.nums[index];
        delta = val-ori;
        self.bit.add(index, delta);
        self.nums[index] = val;

    def sumRange(self, left: int, right: int) -> int:
        result = self.bit.range_sum(left, right);
        return result;

