import random
from typing import List

class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        n = len(nums)
        target = n - k  # 第 k 大 = 升序里的第 n-k 个

        left, right = 0, n - 1

        while left <= right:
            pivot = nums[random.randint(left, right)]

            lt = left      # nums[left:lt] < pivot
            i = left       # nums[lt:i] == pivot
            gt = right     # nums[gt+1:right+1] > pivot

            while i <= gt:
                if nums[i] < pivot:
                    nums[lt], nums[i] = nums[i], nums[lt]
                    lt += 1
                    i += 1
                elif nums[i] > pivot:
                    nums[i], nums[gt] = nums[gt], nums[i]
                    gt -= 1
                else:
                    i += 1

            # partition 后：
            # nums[left:lt] < pivot
            # nums[lt:gt+1] == pivot
            # nums[gt+1:right+1] > pivot

            if target < lt:
                right = lt - 1
            elif target > gt:
                left = gt + 1
            else:
                return nums[target]

