class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        def dfs(root: 'TreeNode', target: int)->[int]:
            if root is None:
                return;
            if root.val == target:
                return [root];
            a = dfs(root.left, target);
            b = dfs(root.right, target);
            if a is not None:
                return a+[root];
            elif b is not None:
                return b+[root];
            return None;
        pl = dfs(root, p.val);
        ql = dfs(root, q.val);
        for i in ql:
            if i in pl:
                return i;
        return root;

