class Codec:

    def serialize(self, root):
        """Encodes a tree to a single string.

        :type root: TreeNode
        :rtype: str
        """
        order = [];
        stack = deque([root]);
        while stack:
            for i in range(len(stack)):
                root = stack.popleft();
                if root:
                    order.append(str(root.val));
                    stack.append(root.left);
                    stack.append(root.right);
                else:
                    order.append('1001');
        return "#".join(order);



    def deserialize(self, data):
        """Decodes your encoded data to tree.

        :type data: str
        :rtype: TreeNode
        """
        inputlist = deque(data.split("#"));
        rootv = int(inputlist.popleft());
        rootstack = deque([]);
        rootNode = None;
        if rootv!= 1001:
            rootNode = TreeNode(rootv);
            rootstack.append(rootNode);
        while inputlist and rootstack:
            root = rootstack.popleft();
            leftv = int(inputlist.popleft());
            rightv = int(inputlist.popleft());
            left = None;
            right = None;
            if leftv != 1001:
                left = TreeNode(leftv);
                rootstack.append(left)
            if rightv != 1001:
                right = TreeNode(rightv);
                rootstack.append(right);
            root.left = left;
            root.right = right;
        return rootNode;







