            return None;
        rootv = int(inputlist[0]);
        rootNode = TreeNode(rootv);
        rootstack = deque([rootNode]);
        i = 1;
        while rootstack:
            root = rootstack.popleft();
            if inputlist[i] != 'N':
                root.left = TreeNode(int(inputlist[i]));
                rootstack.append(root.left)
            i+=1;
            if inputlist[i] != 'N':
                root.right = TreeNode(int(inputlist[i]));
                rootstack.append(root.right);
            i+=1;
        return rootNode;







