class Codec:

    def serialize(self, root):
        res = []

        def dfs(node):
            if node is None:
                res.append("N")
                return

            res.append(str(node.val))
            dfs(node.left)
            dfs(node.right)

        dfs(root)
        return ",".join(res)

    def deserialize(self, data):
        vals = deque(data.split(","))

        def dfs():
            val = vals.popleft()

            if val == "N":
                return None

            node = TreeNode(int(val))
            node.left = dfs()
            node.right = dfs()
            return node

        return dfs()

