        dist = [float('inf') for _ in range(n+1)];
        dic = defaultdict(list);
        dist[k] = 0;
        dist[0] = 0;
        for u,v,w in times:
            dic[u].append([v,w]);
        heap = [[0, k]];
        while heap:
            d, node = heapq.heappop(heap);
            if d< dist[node]:
                continue;
            for nei,w in dic[node]:
                nd = w+d;
                if nd < dist[nei]:
                    heapq.heappush(heap, [nd, nei]);
                    dist[nei] = nd;

        return max(dist) if max(dist) != float('inf') else -1;

