            return 0

        n = len(beginWord)

        candidates = defaultdict(set)
        for word in wordList:
            for i in range(n):
                candidates[i].add(word[i])

        q = deque([beginWord])
        dic.discard(beginWord)

        steps = 1

        while q:
            for _ in range(len(q)):
                word = q.popleft()

                if word == endWord:
                    return steps

                for i in range(n):
                    for char in candidates[i]:
                        if char == word[i]:
                            continue

                        newword = word[:i] + char + word[i + 1:]

                        if newword in dic:
                            dic.remove(newword)
                            q.append(newword)

            steps += 1

        return 0

