class Solution:
    def shortestAlternatingPaths(
        self,
        n: int,
        redEdges: List[List[int]],
        blueEdges: List[List[int]]
    ) -> List[int]:

        graph = [defaultdict(list), defaultdict(list)]

        for u, v in redEdges:
            graph[0][u].append(v)

        for u, v in blueEdges:
            graph[1][u].append(v)

        ans = [-1] * n
        q = deque([(0, 0), (0, 1)])
        visited = {(0, 0), (0, 1)}

        dist = 0

        while q:
            for _ in range(len(q)):
                node, color = q.popleft()

                if ans[node] == -1:
                    ans[node] = dist

                next_color = 1 - color

                for nei in graph[next_color][node]:
                    state = (nei, next_color)
                    if state not in visited:
                        visited.add(state)
                        q.append(state)

            dist += 1

        return ans

