class Solution:
    def longestUnivaluePath(self, root: Optional[TreeNode]) -> int:
        result = 0

        def dfs(node):
            nonlocal result

            if node is None:
                return 0

            left_length = dfs(node.left)
            right_length = dfs(node.right)

            left_path = 0
            right_path = 0

            if node.left is not None and node.left.val == node.val:
