        INT_MAX = 2**31 - 1

        result = 0

        while x != 0:
            # Python 的 // 对负数向下取整，
            # 这里手动模拟 C++ / Java 的向 0 截断
            quotient = x // 10
            if x < 0 and x % 10 != 0:
                quotient += 1

            digit = x - quotient * 10
