    def nextPermutation(self, nums: List[int]) -> None:
        n = len(nums)

        # 1. 从右往左找到第一个 nums[i] < nums[i + 1]
        i = n - 2
        while i >= 0 and nums[i] >= nums[i + 1]:
            i -= 1

        # 2. 如果找到了下降点
        if i >= 0:
            # 从右往左找第一个大于 nums[i] 的元素
            j = n - 1
            while nums[j] <= nums[i]:
                j -= 1

            nums[i], nums[j] = nums[j], nums[i]

        # 3. 反转 i 后面的降序区间
