class Solution:
    def minRemovals(self, nums: List[int], target: int) -> int:
        dp = {0:0};
        for num in nums:
            nextdp = dp.copy();
            for key, value in dp.items():
                newxor = key ^ num;
                newvalue = max(nextdp.get(newxor, -1), value+1);
                nextdp[newxor] = newvalue;
            dp = nextdp;
        if target not in dp:
            return -1;
        return len(nums)-dp[target];

