        def dfs(node,a,b):
            if node is None:
                return a,b;
            a = max(a, node.val);
            b = min(b, node.val);
            la,lb = dfs(node.left, a,b);
            ra,rb = dfs(node.right, a,b);
            if abs(la-lb) > abs(ra-rb):
                return la,lb;
            else:
                return ra,rb;
        a,b = dfs(root,0,float('inf'));
        return abs(a-b);

