class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        result = []
        posi = set()

        def helper(i, j, ii, jj):
            if ii == i or jj == j:
                return False
            if abs(ii - i) == abs(jj - j):
                return False
            return True

        def dfs(row):
            # 已经成功放了 n 个皇后
            if row == n:
                board = []

                for i in range(n):
                    line = ["."] * n
                    for x, y in posi:
                        if x == i:
                            line[y] = "Q"
                    board.append("".join(line))

                result.append(board)
                return

            # 当前 row 行选择一个位置
            for j in range(n):

                # 必须和所有已经放置的皇后都不冲突
                if all(helper(row, j, pi, pj) for pi, pj in posi):
                    posi.add((row, j))

                    dfs(row + 1)

                    # backtracking
                    posi.remove((row, j))

        dfs(0)
        return result

