            # 已经成功放了 n 个皇后
            if row == n:
                result.append(["".join(r) for r in board])
                return

            # 当前 row 行选择一个位置
            for j in range(n):

                # 必须和所有已经放置的皇后都不冲突
                if j not in posi and row-j not in diag1 and row+j not in diag2:
