        used = [False] * len(tiles)

        def dfs():
            ans = 0

            for i in range(len(tiles)):
                if used[i]:
                    continue

                # 相同字母在同一层只选第一个，避免重复
                if i > 0 and tiles[i] == tiles[i - 1] and not used[i - 1]:
                    continue

                used[i] = True

                # 选了这个字母，就多出一个合法字符串
                ans += 1

                # 再继续往后选
                ans += dfs()

                used[i] = False

            return ans

        return dfs()

