class Solution:
    def subarraySum(self, nums, k):
        left = total = answer = 0
        for right, value in enumerate(nums):
            total += value
            while total > k and left <= right:
                total -= nums[left]
                left += 1
            if total == k:
                answer += 1
        return answer

