            for c in word:
                if freq[c] < ff[c]:
                    return False;
            return True;
        def dfs(start, total):
            nonlocal result;
            for i in range(start,n):
                word = words[i];
                vv= 0;
                picked = 0
                if pickable(word):
                    picked = 1;
                    for ii in word:
                        vv  += score[ord(ii) - ord('a')];
                        freq[ii] -=1;
                total += vv;
                result = max(result, total);
                dfs(i+1, total);
                total -= vv
                if picked == 1:
                    for ii in word:
                        freq[ii] +=1;

        dfs(0,0);
        return result;

from collections import Counter
class Solution:
    def maxScoreWords(self, words: List[str], letters: List[str], score: List[int]) -> int:
        freq = Counter(letters);
        n = len(words);
        result = 0;
        needs = [Counter(word) for word in words];
        values = [
            sum(score[ord(c) - ord('a')] for c in word)
            for word in words
        ]
        def pickable(i):
            for k,v in needs[i].items():
                if freq[k] < v:
                    return False;
            return True;
        def dfs(start, total):
            nonlocal result;
            result = max(result, total);
            for i in range(start,n):
                if not pickable(i):
                    continue;
                for c, cnt in needs[i].items():
                    freq[c] -= cnt;
                dfs(i+1, total + values[i]);
                for c, cnt in needs[i].items():
                    freq[c] += cnt;

        dfs(0,0);
        return result;

