class Solution:
    def smallestSubsequence(self, s: str) -> str:
        n = len(s);
        last = defaultdict(int);
        for i in range(n):
            last[s[i]] = max(last[s[i]], i);
        start = 0;
        seen = set();
        stack = [];
        while start<n:
            letter = s[start];
            if letter in seen:
                start +=1;
